import pytest


def shout(xs: list[str]) -> None:
    """Print each string in xs upper-cased, one per line."""
    for s in xs:
        print(s.upper())


def test_shout_upper_cases_each_line(capsys: pytest.CaptureFixture[str]) -> None:
    shout(["abc", "Hi there"])
    assert capsys.readouterr().out == "ABC\nHI THERE\n"


def test_shout_empty_list_prints_nothing(capsys: pytest.CaptureFixture[str]) -> None:
    shout([])
    assert capsys.readouterr().out == ""


def test_shout_empty_string_prints_blank_line(capsys: pytest.CaptureFixture[str]) -> None:
    shout([""])
    assert capsys.readouterr().out == "\n"
